export const hairJourneyThreadsVertex = "precision highp float;\n\nuniform float uTime;\nuniform float uFinalProgress;\nuniform vec2 uMouse;\nuniform vec2 uFrameScale;\nuniform float uQuality;\n\nattribute float aRibbonIndex;\nattribute vec4 aRandom;\nattribute float aBandUv;\n\nvarying vec2 vUv;\nvarying float vBandUv;\nvarying float vUnwoven;\nvarying float vRandom;\nvarying float vOpacity;\n\nvoid main() {\n  vUv = uv;\n  vBandUv = aBandUv;\n  vRandom = aRandom.x;\n\n  float progress = clamp(uFinalProgress, 0.0, 1.0);\n  float birth = smoothstep(0.015, 0.2, progress);\n  float spread = smoothstep(0.05, 0.4, progress);\n  float settle = smoothstep(0.48, 0.96, progress);\n  float unwoven = sin(smoothstep(0.0, 1.0, progress) * 3.14159265);\n  unwoven *= 1.0 - settle * 0.72;\n  vUnwoven = unwoven;\n  vOpacity = birth;\n\n  vec2 transformed = position.xy;\n  vec2 collapsedScale = vec2(0.095, 0.72);\n  transformed *= mix(collapsedScale, uFrameScale, spread);\n\n  float outerRibbon = abs(aRibbonIndex * 2.0 - 1.0);\n  float edgeMotion = 0.28 + pow(outerRibbon, 1.4) * 0.72;\n  float phase = aRandom.x * 14.0 + aRibbonIndex * 10.0;\n  float primaryWave = sin(position.x * mix(5.0, 9.0, aRandom.y) + phase + uTime * 0.42);\n  float fineWave = sin(position.x * 17.0 - uTime * 0.25 + phase * 0.7);\n  transformed.y += (primaryWave * 0.052 + fineWave * 0.014) * unwoven * edgeMotion * uQuality;\n  transformed.x += (aRandom.z - 0.5) * 0.1 * unwoven * edgeMotion;\n  transformed.y += (aRandom.y - 0.5) * 0.065 * unwoven;\n  transformed.x += uMouse.x * 0.018 * unwoven;\n  transformed.y += uMouse.y * 0.012 * unwoven * edgeMotion;\n\n  gl_Position = vec4(transformed, 0.0, 1.0);\n}\n";
export const hairJourneyThreadsFragment = "precision highp float;\n\nuniform sampler2D uTexture;\nuniform float uQuality;\n\nvarying vec2 vUv;\nvarying float vBandUv;\nvarying float vUnwoven;\nvarying float vRandom;\nvarying float vOpacity;\n\nvoid main() {\n  float shift = vUnwoven * mix(0.00025, 0.001, uQuality) * (0.7 + vRandom * 0.3);\n  vec4 source = texture2D(uTexture, vUv);\n  vec3 color = vec3(\n    texture2D(uTexture, vUv + vec2(shift, 0.0)).r,\n    source.g,\n    texture2D(uTexture, vUv - vec2(shift, 0.0)).b\n  );\n\n  float bandDistance = min(vBandUv, 1.0 - vBandUv) * 2.0;\n  float bandEdge = 1.0 - smoothstep(0.0, 0.18, bandDistance);\n  color += vec3(0.78, 0.8, 0.84) * bandEdge * vUnwoven * 0.035;\n  float ribbonFade = mix(1.0, smoothstep(0.0, 0.12, bandDistance), vUnwoven * 0.5);\n  float photoEdge = smoothstep(0.0, 0.018, vUv.x) * smoothstep(0.0, 0.018, 1.0 - vUv.x);\n  float alpha = source.a * vOpacity * ribbonFade * photoEdge;\n\n  gl_FragColor = vec4(color, alpha);\n  #include <colorspace_fragment>\n}\n";
export const particleVertex = "attribute vec3 randomPosition;\nattribute vec3 targetPosition;\nattribute vec3 sampleColor;\nuniform float uProgress;\nuniform float uTime;\nuniform float uDpr;\nuniform float uPointSize;\nuniform vec4 uImageRect;\nvarying float vAlpha;\nvarying vec3 vColor;\nvarying float vEnergy;\nvoid main() {\n  vec2 targetUV = uImageRect.xy + targetPosition.xy * uImageRect.zw;\n  vec2 target = vec2(targetUV.x * 2.0 - 1.0, 1.0 - targetUV.y * 2.0);\n  float delay = randomPosition.z * .13 + targetPosition.y * .035;\n  float progress = smoothstep(0.0, 1.0, clamp((uProgress - delay) / .84, 0.0, 1.0));\n  float inverse = 1.0 - progress;\n  float side = sign(randomPosition.x);\n  vec2 control = mix(randomPosition.xy, target, .5);\n  control += vec2(-side * (.2 + randomPosition.z * .22), (randomPosition.z - .5) * .62);\n  vec2 p = inverse * inverse * randomPosition.xy + 2.0 * inverse * progress * control + progress * progress * target;\n  vec2 tangent = normalize(vec2(-(target.y - control.y), target.x - control.x) + vec2(.001));\n  float curl = sin(progress * 3.14159) * (.055 + randomPosition.z * .07);\n  p += tangent * curl * sin(uTime * 2.4 + randomPosition.z * 24.0 + target.y * 5.0);\n  p += (randomPosition.z - .5) * vec2(.07, .035) * inverse;\n  float lockPulse = exp(-pow((uTime - 1.82) * 6.0, 2.0));\n  gl_Position = vec4(p, (randomPosition.z - .5) * .12 * inverse, 1.0);\n  gl_PointSize = uPointSize * uDpr * (.58 + randomPosition.z * .35 + lockPulse * .42);\n  vAlpha = .56 + targetPosition.z * .36;\n  vEnergy = sin(progress * 3.14159) * .42 + lockPulse;\n  vec3 noirBlue = mix(vec3(.24, .38, .68), vec3(.68, .55, .9), randomPosition.z);\n  float sourceMix = smoothstep(.72, 1.0, progress);\n  vColor = mix(noirBlue, sampleColor * 1.28 + vec3(.035), sourceMix);\n}\n";
export const particleFragment = "uniform float uOpacity;\nvarying float vAlpha;\nvarying vec3 vColor;\nvarying float vEnergy;\nvoid main() {\n  float distanceToCenter = length(gl_PointCoord - .5);\n  float halo = (1.0 - smoothstep(.12, .5, distanceToCenter)) * .3;\n  float core = 1.0 - smoothstep(.025, .16, distanceToCenter);\n  float alpha = (halo + core * .8) * vAlpha * uOpacity;\n  gl_FragColor = vec4(vColor * (.86 + core * .72 + vEnergy * .42), alpha);\n  #include <colorspace_fragment>\n}\n";
